import { humanize } from './humanize';
import { extractAttributes } from './schemaMapping';
import { isEmpty, nodeAt, otherNamePath } from './reviewPapers';

/**
 * Coding a review's papers against its schema: which fields there are and
 * how to read and write them, for the coding form
 * (components/CodePaperModal.jsx).
 *
 * A field is { attribute, path, rel, label, hint, level, group, other }:
 *   rel    the path inside the paper, or inside an artifact for
 *          level 'artifact' (attributes under contribution.artifacts[])
 *   group  the object holding it, e.g. "metadata" or "contribution.focus_intent"
 *   other  the field holding the name of an "Other" value, when the schema
 *          has one ("<name>_other" next to it, or "other" in the same object)
 */

const ARTIFACTS = 'contribution.artifacts[]';

export const fieldLabel = (attribute) => attribute.annotation?.label || humanize(attribute.annotation?.key || attribute.name);

/** An object with its own x-ariadne settings is one attribute for the
 * views (e.g. Implementation, read as a whole), but is coded part by part:
 * its properties become attributes of their own, labelled "Object: Part". */
function codedAttributes(schema, attributes) {
  return attributes.flatMap((a) => {
    if (a.kind !== 'composite') return [a];
    const node = nodeAt(schema, a.path);
    const parts = extractAttributes({ type: 'object', properties: node?.properties || {} });
    return parts.map((p) => ({
      ...p,
      path: `${a.path}.${p.path}`,
      annotation: { ...(p.annotation || {}), label: p.annotation?.label || `${fieldLabel(a)}: ${humanize(p.name)}` },
    }));
  });
}

function toField(attribute, schema) {
  const inArtifact = attribute.path.startsWith(`${ARTIFACTS}.`);
  const rel = inArtifact ? attribute.path.slice(ARTIFACTS.length + 1) : attribute.path;
  const segments = rel.split('.');
  return {
    attribute,
    path: attribute.path,
    rel,
    label: fieldLabel(attribute),
    hint: attribute.description || '',
    level: inArtifact ? 'artifact' : 'paper',
    group: segments.slice(0, -1).join('.'),
    // A single choice stored as a list of one value.
    asList: attribute.kind === 'single' && nodeAt(schema, attribute.path)?.type === 'array',
    other: null,
  };
}

/** The fields of a schema, in schema order: { fields, paperFields,
 * artifactFields, hasArtifacts }. Fields holding an "Other" name hang off
 * the field they name (field.other) and are not listed on their own. */
export function codingPlan(schema) {
  const attributes = extractAttributes(schema);
  const fields = codedAttributes(schema, attributes).map((a) => toField(a, schema));
  const byPath = new Map(fields.map((f) => [f.path, f]));
  const owned = new Set();
  fields.forEach((f) => {
    if (!f.attribute.values?.some((v) => /^other$/i.test(v))) return;
    const namePath = otherNamePath(schema, f.attribute);
    // Without a field for the name in the schema, it is kept next to the
    // choice anyway (see otherNamePath).
    const nameField = byPath.get(namePath)
      || toField({ path: namePath, name: namePath.split('.').pop(), kind: 'text', values: null, description: '', annotation: null }, schema);
    if (!owned.has(namePath)) {
      f.other = nameField;
      owned.add(namePath);
    }
  });
  const listed = fields.filter((f) => !owned.has(f.path));
  return {
    attributes,
    fields: listed,
    paperFields: listed.filter((f) => f.level === 'paper'),
    artifactFields: listed.filter((f) => f.level === 'artifact'),
    hasArtifacts: listed.some((f) => f.level === 'artifact'),
  };
}

/** Fields grouped by the object holding them, in first-seen order:
 * [{ id, title, fields }]. */
export function groupFields(fields) {
  const groups = [];
  fields.forEach((f) => {
    let g = groups.find((x) => x.id === f.group);
    if (!g) {
      const last = f.group.split('.').pop();
      g = { id: f.group, title: f.group === 'metadata' ? 'Bibliographic Data' : f.group === 'contribution' || !f.group ? 'Coding' : humanize(last), fields: [] };
      groups.push(g);
    }
    g.fields.push(f);
  });
  return groups;
}

const segmentsOf = (rel) => rel.split('.');

/** The value at a field's path in a paper (or artifact). */
export function readValue(node, rel) {
  return segmentsOf(rel).reduce((cur, k) => (cur && typeof cur === 'object' ? cur[k] : undefined), node);
}

/** A copy of the node with the value set at rel; an empty value removes the
 * key. Objects on the way are created as needed. */
export function writeValue(node, rel, value) {
  const keys = segmentsOf(rel);
  // Clearing a value that is not there changes nothing.
  if (isEmpty(value) && readValue(node, rel) === undefined) return node;
  const copy = { ...node };
  let cur = copy;
  keys.slice(0, -1).forEach((k) => {
    cur[k] = cur[k] && typeof cur[k] === 'object' && !Array.isArray(cur[k]) ? { ...cur[k] } : {};
    cur = cur[k];
  });
  const last = keys[keys.length - 1];
  if (isEmpty(value)) delete cur[last];
  else cur[last] = value;
  return copy;
}

export const artifactsOf = (paper) => (Array.isArray(paper.contribution?.artifacts) ? paper.contribution.artifacts : []);

/** A copy of the paper with its artifacts replaced. */
export function withArtifacts(paper, artifacts) {
  const contribution = { ...(paper.contribution || {}) };
  if (artifacts.length) contribution.artifacts = artifacts;
  else delete contribution.artifacts;
  return { ...paper, contribution };
}

/** Writes a field's value into a paper; for artifact fields, into its
 * artifact number `artifactIndex`. */
export function setField(paper, field, rawValue, artifactIndex = 0) {
  const value = field.asList && typeof rawValue === 'string' ? [rawValue] : rawValue;
  if (field.level === 'paper') return writeValue(paper, field.rel, value);
  const artifacts = [...artifactsOf(paper)];
  while (artifacts.length <= artifactIndex) artifacts.push({});
  artifacts[artifactIndex] = writeValue(artifacts[artifactIndex], field.rel, value);
  return withArtifacts(paper, artifacts);
}

export const choseOther = (value) => (Array.isArray(value) ? value : [value]).some((v) => typeof v === 'string' && /^other$/i.test(v));

/** The index of the next paper after `from` (wrapping around) that is not
 * fully coded, or -1 when every other paper is. */
export function nextToCode(papers, from, statusOf) {
  for (let step = 1; step <= papers.length; step += 1) {
    const i = (from + step) % papers.length;
    if (i !== from && statusOf(papers[i]) !== 'coded') return i;
  }
  return -1;
}
