import { useEffect, useMemo, useRef, useState } from 'react';
import { getDataSource, saveReviewPapers } from '@/lib/data';
import { humanize } from '@/lib/humanize';
import { artifactsOf, choseOther, codingPlan, groupFields, nextToCode, readValue, setField, withArtifacts } from '@/lib/coding';
import { codingStatusOf, CODING } from '@/lib/review';
import { checkPaper, isEmpty } from '@/lib/reviewPapers';
import { NAMED, NAME_SEPARATOR, isNamed, isOtherId, joinList, namedChips, rankNames, splitList, splitNames, toggleMulti, toggleSingle } from '@/lib/formLists';
import ChipSelect from '@/components/ChipSelect';

const plural = (n, one, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;
const LONG_TEXT = 60;

/** A free list typed as comma-separated text. The text is kept while
 * typing, so a trailing comma or space is not swallowed. */
function ListInput({ id, value, onChange, placeholder }) {
  const [text, setText] = useState(() => joinList(value));
  // Follows changes from outside (another paper, a cleared value).
  useEffect(() => {
    if (JSON.stringify(splitList(text)) !== JSON.stringify(Array.isArray(value) ? value : [])) setText(joinList(value));
  }, [value]); // eslint-disable-line react-hooks/exhaustive-deps
  return (
    <input id={id} className="toolbar__search" value={text} placeholder={placeholder}
      onChange={(e) => { setText(e.target.value); onChange(splitList(e.target.value)); }} />
  );
}

const YES_NO = [{ id: 'yes', label: 'Yes' }, { id: 'no', label: 'No' }];
const OTHER = 'other';
const lower = (n) => n.toLowerCase();

/**
 * How a choice offering "Other" stands in a paper or artifact. Names typed
 * for "Other" in the review's other papers (`learned`) are chips of their
 * own; names not among them are "typed", shown in the Other box. The box is
 * open when the visitor opened it (`override`) or, by default, when the
 * value has typed names or "other" has no name yet.
 */
function otherState(field, node, learned, override) {
  const value = readValue(node, field.rel);
  const selected = isEmpty(value) ? [] : Array.isArray(value) ? value : [value];
  const names = splitNames(readValue(node, field.other.rel));
  const known = new Map(learned.map((n) => [lower(n), n]));
  const chipNames = names.filter((n) => known.has(lower(n))).map((n) => known.get(lower(n)));
  const typed = names.filter((n) => !known.has(lower(n)));
  const hasOther = selected.some(isOtherId);
  const open = override ?? (hasOther && (typed.length > 0 || names.length === 0));
  return { selected, chipNames, typed, open };
}

/** One field, by the attribute's kind: choices and yes/no as chips (with
 * the required name of an "Other" value), numbers, lists as comma-separated
 * text, and text. */
function FieldRow({ field, node, onSet, idPrefix, choice }) {
  const { kind, values } = field.attribute;
  const value = readValue(node, field.rel);
  const id = `${idPrefix}-${field.path}`;
  const key = `${idPrefix}|${field.path}`;
  // The name field takes the cursor only right after Other is picked, not
  // when a paper opens with Other already chosen.
  const [pickedOther, setPickedOther] = useState(false);
  const st = field.other ? otherState(field, node, choice.learned[field.path] || [], choice.otherOpen[key]) : null;
  const typedNow = st ? st.typed.join(NAME_SEPARATOR) : '';
  // The Other box keeps its text while typing (e.g. a trailing "; ").
  const [typedText, setTypedText] = useState(typedNow);
  useEffect(() => {
    if (splitNames(typedText).join(NAME_SEPARATOR) !== typedNow) setTypedText(typedNow);
  }, [typedNow]); // eslint-disable-line react-hooks/exhaustive-deps

  if ((kind === 'single' || kind === 'multi') && values && st) {
    // Writes the choice and the names of its "Other" values together.
    const write = ({ base, chips, open, text }) => {
      const names = [...chips, ...(open ? splitNames(text) : [])];
      const withOther = names.length > 0 || open;
      const plain = base.filter((v) => !isOtherId(v));
      choice.setOpen(key, open);
      onSet(field.other, names.join(NAME_SEPARATOR));
      onSet(field, kind === 'multi' ? [...plain, ...(withOther ? [OTHER] : [])] : withOther ? OTHER : plain[0]);
    };
    const toggle = (v) => {
      setPickedOther(false);
      if (isNamed(v)) {
        const name = v.slice(NAMED.length);
        if (kind === 'multi') write({ base: st.selected, chips: toggleMulti(st.chipNames, name), open: st.open, text: typedText });
        else {
          setTypedText('');
          write({ base: [], chips: st.chipNames.includes(name) ? [] : [name], open: false, text: '' });
        }
      } else if (isOtherId(v)) {
        const open = !st.open;
        setPickedOther(open);
        if (!open) setTypedText('');
        write({ base: kind === 'multi' ? st.selected : [], chips: kind === 'multi' ? st.chipNames : [], open, text: open ? typedText : '' });
      } else if (kind === 'multi') {
        write({ base: toggleMulti(st.selected, v), chips: st.chipNames, open: st.open, text: typedText });
      } else {
        setTypedText('');
        write({ base: toggleSingle(st.selected.filter((x) => !isOtherId(x)), v), chips: [], open: false, text: '' });
      }
    };
    const options = [
      ...values.filter((v) => !isOtherId(v)).map((v) => ({ id: v, label: humanize(v) })),
      ...namedChips(choice.learned[field.path] || []),
      { id: OTHER, label: humanize(OTHER) },
    ];
    const selected = [
      ...st.selected.filter((v) => !isOtherId(v)),
      ...st.chipNames.map((n) => `${NAMED}${n}`),
      ...(st.open ? [OTHER] : []),
    ];
    return (
      <ChipSelect label={field.label} hint={field.hint} options={options} selected={selected} onToggle={toggle}
        other={{
          id: `${id}-other`,
          label: 'Name of the other value',
          placeholder: 'Several names separated by ;',
          value: typedText,
          onChange: (text) => {
            setTypedText(text);
            write({ base: st.selected, chips: st.chipNames, open: true, text });
          },
          showError: choice.attempted,
          autoFocus: pickedOther,
        }} />
    );
  }
  if ((kind === 'single' || kind === 'multi') && values) {
    const selected = isEmpty(value) ? [] : Array.isArray(value) ? value : [value];
    return (
      <ChipSelect label={field.label} hint={field.hint} options={values.map((v) => ({ id: v, label: humanize(v) }))}
        selected={selected}
        onToggle={(v) => onSet(field, kind === 'multi' ? toggleMulti(selected, v) : toggleSingle(selected, v)[0])} />
    );
  }
  if (kind === 'boolean') {
    const selected = value === true ? ['yes'] : value === false ? ['no'] : [];
    return (
      <ChipSelect label={field.label} hint={field.hint} options={YES_NO} selected={selected}
        onToggle={(v) => { const next = toggleSingle(selected, v)[0]; onSet(field, next === undefined ? undefined : next === 'yes'); }} />
    );
  }

  let input;
  if (kind === 'number') {
    input = (
      <input id={id} type="number" className="toolbar__search coding-form__number" value={value ?? ''}
        onChange={(e) => onSet(field, e.target.value === '' ? undefined : Number.isFinite(e.target.valueAsNumber) ? e.target.valueAsNumber : e.target.value)} />
    );
  } else if (kind === 'list' || kind === 'multi') {
    input = <ListInput id={id} value={value} placeholder="Separate entries with commas" onChange={(v) => onSet(field, v)} />;
  } else {
    const text = value ?? '';
    input = String(text).length > LONG_TEXT || /goal|question|description|summary|note|abstract/i.test(field.attribute.name)
      ? <textarea id={id} className="add-paper__textarea" rows={2} value={text} onChange={(e) => onSet(field, e.target.value)} />
      : <input id={id} className="toolbar__search" value={text} onChange={(e) => onSet(field, e.target.value)} />;
  }
  return (
    <div className="add-paper__field coding-form__field">
      <label className="filters-panel__label" htmlFor={id}>{field.label}</label>
      {field.hint && <p className="add-paper__hint coding-form__hint">{field.hint}</p>}
      {input}
    </div>
  );
}

function Groups({ fields, node, onSet, idPrefix, choice, collapse = [] }) {
  return groupFields(fields).map((g) => {
    const body = g.fields.map((f) => <FieldRow key={f.path} field={f} node={node} onSet={onSet} idPrefix={idPrefix} choice={choice} />);
    const filled = g.fields.filter((f) => !isEmpty(readValue(node, f.rel))).length;
    return collapse.includes(g.id) ? (
      <details key={g.id} className="coding-form__group">
        <summary className="add-paper__section">{g.title} <span className="coding-form__count">{filled} of {g.fields.length} filled</span></summary>
        {body}
      </details>
    ) : (
      <section key={g.id} className="coding-form__group">
        <h3 className="add-paper__section">{g.title}</h3>
        {body}
      </section>
    );
  });
}

/**
 * Codes the papers of the visitor's own review, one at a time, in a form
 * built from the review's schema. Saves go straight into the stored review;
 * "Save and Code Next" moves on to the next paper not fully coded.
 * onClose(changed) tells whether anything was saved.
 */
export default function CodePaperModal({ startIndex = null, onClose }) {
  const source = getDataSource();
  const schema = source.schema;
  const plan = useMemo(() => codingPlan(schema), [schema]);
  const [papers, setPapers] = useState(source.papers || []);
  const firstIndex = startIndex ?? (() => {
    const i = papers.findIndex((p) => codingStatusOf(p) !== 'coded');
    return i === -1 ? 0 : i;
  })();
  const [index, setIndex] = useState(firstIndex);
  const [draft, setDraft] = useState(papers[firstIndex] || null);
  const [dirty, setDirty] = useState(false);
  const [changed, setChanged] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);
  const [note, setNote] = useState(null);
  // Set by a save; shows the missing "Other" names, as in Add Paper.
  const [attempted, setAttempted] = useState(false);
  // Other boxes opened or closed by the visitor, by "<idPrefix>|<path>".
  const [otherOpen, setOtherOpen] = useState({});
  const bodyRef = useRef(null);

  // Names typed for "Other" in the review's other papers, per field, most
  // used first: offered as chips of their own (as in Add Paper).
  const learned = useMemo(() => {
    const out = {};
    plan.fields.filter((f) => f.other).forEach((f) => {
      const names = papers.flatMap((p, i) => (i === index ? [] : (f.level === 'paper' ? [p] : artifactsOf(p)))
        .flatMap((n) => splitNames(readValue(n, f.other.rel))));
      out[f.path] = rankNames(names);
    });
    return out;
  }, [papers, index, plan]);
  const choice = {
    attempted,
    learned,
    otherOpen,
    setOpen: (key, open) => setOtherOpen((o) => (o[key] === open ? o : { ...o, [key]: open })),
  };

  const check = useMemo(() => (draft ? checkPaper(draft, schema, plan.attributes) : null), [draft, schema, plan]);
  const status = !check ? null : check.errors.length ? 'problems' : check.uncoded.length ? 'uncoded' : 'coded';
  const missingOther = useMemo(() => {
    if (!draft) return false;
    const nodes = (f) => (f.level === 'paper' ? [['paper', draft]] : artifactsOf(draft).map((a, i) => [`artifact${i}`, a]));
    // An open Other box needs a name of its own; "other" needs some name.
    return plan.fields.some((f) => f.other && nodes(f).some(([prefix, n]) => {
      const st = otherState(f, n, learned[f.path] || [], otherOpen[`${prefix}|${f.path}`]);
      return (st.open && !st.typed.length) || (choseOther(readValue(n, f.rel)) && !st.typed.length && !st.chipNames.length);
    }));
  }, [draft, plan, learned, otherOpen]);
  const remaining = papers.filter((p, i) => (i === index ? status : codingStatusOf(p)) !== 'coded').length;

  const close = () => {
    if (dirty && !window.confirm('Close without saving the changes to this paper?')) return;
    onClose(changed);
  };

  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') close(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  });

  const go = (i, list = papers) => {
    setIndex(i);
    setDraft(list[i]);
    setDirty(false);
    setError(null);
    setAttempted(false);
    setOtherOpen({});
    bodyRef.current?.scrollTo({ top: 0 });
  };

  const set = (artifactIndex) => (field, value) => {
    setDraft((d) => setField(d, field, value, artifactIndex));
    setDirty(true);
    setNote(null);
    setError(null);
  };

  const addArtifact = () => {
    setDraft((d) => withArtifacts(d, [...artifactsOf(d), {}]));
    setDirty(true);
  };
  const removeArtifact = (i) => {
    const art = artifactsOf(draft)[i];
    const filled = plan.artifactFields.some((f) => !isEmpty(readValue(art, f.rel)));
    if (filled && !window.confirm(`Remove artifact ${i + 1} and its codes?`)) return;
    setDraft((d) => withArtifacts(d, artifactsOf(d).filter((_, j) => j !== i)));
    setDirty(true);
  };

  const save = async (thenNext) => {
    if (dirty && missingOther) {
      // "Other" needs its name before the paper is saved.
      setAttempted(true);
      setNote(null);
      setError('Name every "Other" value before saving, or pick a listed value instead.');
      return;
    }
    setSaving(true);
    setError(null);
    try {
      let list = papers;
      if (dirty) {
        list = papers.map((p, i) => (i === index ? draft : p));
        await saveReviewPapers(list);
        setPapers(list);
        setChanged(true);
        setDirty(false);
      }
      if (thenNext) {
        const next = nextToCode(list, index, codingStatusOf);
        if (next === -1) setNote('Saved. Every paper of your review is fully coded.');
        else {
          go(next, list);
          setNote(dirty ? `Saved paper ${index + 1}.` : null);
        }
      } else if (dirty) setNote('Saved.');
    } catch (e) {
      setError(`Could not save: ${e.message}`);
    } finally {
      setSaving(false);
    }
  };

  const move = (step) => {
    if (dirty && !window.confirm('Leave this paper without saving its changes?')) return;
    go((index + step + papers.length) % papers.length);
    setNote(null);
  };

  if (!draft) {
    return (
      <>
        <div className="modal__backdrop" onClick={() => onClose(false)} />
        <div className="modal" role="dialog" aria-modal="true" aria-label="Code papers">
          <div className="modal__body">
            <p className="add-paper__hint">Your review has no papers to code yet. Load papers on the About page first.</p>
            <div className="modal__actions"><button type="button" className="btn btn--primary" onClick={() => onClose(false)}>Close</button></div>
          </div>
        </div>
      </>
    );
  }

  const meta = draft.metadata || {};
  const artifacts = artifactsOf(draft);
  const collapse = ['metadata'];

  return (
    <>
      <div className="modal__backdrop" onClick={close} />
      <div className="modal modal--wide coding-form" role="dialog" aria-modal="true" aria-labelledby="coding-title">
        <div className="modal__header">
          <div className="coding-form__heading">
            <span className="review-banner__eyebrow">Coding paper {index + 1} of {papers.length}</span>
            <h2 id="coding-title">{meta.title || 'Paper without a title'}</h2>
            <p className="add-paper__hint">
              {[Array.isArray(meta.authors) ? meta.authors.join(', ') : meta.authors, meta.year, meta.doi_or_url].filter(Boolean).join(' · ')}
            </p>
          </div>
          <button className="paper-panel__close" onClick={close} aria-label="Close">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M18 6L6 18M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className={`coding-form__status coding-form__status--${status}`} role="status">
          <strong>{CODING[status]}</strong>
          {status === 'uncoded' && <span>Still to code: {check.uncoded.join(', ')}</span>}
          {status === 'problems' && <span>{plural(check.errors.length, 'problem')}, listed below</span>}
          <span className="coding-form__remaining">{remaining === 0 ? 'All papers fully coded' : `${remaining} of ${papers.length} not fully coded`}</span>
        </div>

        <div className="modal__body coding-form__body" ref={bodyRef}>
          <Groups fields={plan.paperFields} node={draft} onSet={set(0)} idPrefix="paper" choice={choice} collapse={collapse} />

          {plan.hasArtifacts && (
            <section className="coding-form__artifacts">
              <h3 className="add-paper__section">Artifacts</h3>
              {artifacts.length === 0 && <p className="add-paper__hint">No artifacts yet. Add one for each contribution of the paper.</p>}
              {artifacts.map((art, i) => (
                <div key={i} className="coding-form__artifact">
                  <div className="coding-form__artifact-head">
                    <strong>Artifact {i + 1}</strong>
                    <button type="button" className="btn btn--ghost btn--sm" onClick={() => removeArtifact(i)}>Remove</button>
                  </div>
                  <Groups fields={plan.artifactFields} node={art} onSet={set(i)} idPrefix={`artifact${i}`} choice={choice} />
                </div>
              ))}
              <button type="button" className="btn btn--secondary btn--sm" onClick={addArtifact}>+ Add Artifact</button>
            </section>
          )}

          {check.errors.length > 0 && (
            <div className="coding-form__problems" role="alert">
              <h3 className="add-paper__section">Problems</h3>
              <ul>{check.errors.map((e) => <li key={e}>{e}</li>)}</ul>
            </div>
          )}
        </div>

        <div className="modal__actions coding-form__actions">
          <div className="coding-form__nav">
            <button type="button" className="btn btn--ghost btn--sm" onClick={() => move(-1)} disabled={saving || papers.length < 2} aria-label="Previous paper">‹ Previous</button>
            <button type="button" className="btn btn--ghost btn--sm" onClick={() => move(1)} disabled={saving || papers.length < 2} aria-label="Next paper">Next ›</button>
          </div>
          {error && <p className="add-paper__error" role="alert">{error}</p>}
          {!error && note && <p className="add-paper__note add-paper__note--success" role="status">{note}</p>}
          <button type="button" className="btn btn--ghost" onClick={close} disabled={saving}>{changed && !dirty ? 'Done' : 'Close'}</button>
          <button type="button" className="btn btn--secondary" onClick={() => save(false)} disabled={saving || !dirty}>Save</button>
          <button type="button" className="btn btn--primary" onClick={() => save(true)} disabled={saving}>
            {dirty ? 'Save and Code Next' : 'Code Next Uncoded'}
          </button>
        </div>
      </div>
    </>
  );
}
